CREATE FUNCTION public.analytics_test_assert(ok boolean,label text) RETURNS void LANGUAGE plpgsql AS $$BEGIN IF ok IS DISTINCT FROM true THEN RAISE EXCEPTION 'FAIL: %',label; END IF;RAISE NOTICE 'PASS: %',label;END$$;
CREATE FUNCTION public.analytics_test_denied(statement text,expected text,label text) RETURNS void LANGUAGE plpgsql AS $$BEGIN BEGIN EXECUTE statement;EXCEPTION WHEN OTHERS THEN IF SQLSTATE=expected THEN RAISE NOTICE 'PASS: %',label;RETURN;END IF;RAISE;END;RAISE EXCEPTION 'FAIL: expected denial: %',label;END$$;
CREATE FUNCTION public.analytics_test_event(event_uuid uuid,route text,country text DEFAULT 'NG') RETURNS jsonb LANGUAGE sql AS $$
 SELECT jsonb_build_object('id',event_uuid,'visitor_id','4b45cbf8-2040-4664-a220-f2ccb1a8b60c','session_id','3ad574e0-f75f-4919-b694-493d553e3544','event_name','page_view','path',route,'country',country,'region',CASE WHEN country IS NULL THEN NULL ELSE 'LA' END,'city',CASE WHEN country IS NULL THEN NULL ELSE 'Lagos' END,'referrer','google.com','source','google','medium','search','campaign','launch','device','mobile','browser','Chrome','os','Android','language','en-NG','abuse_key',repeat('b',64));
$$;
INSERT INTO auth.users(id,email,raw_user_meta_data) VALUES('4c1895bb-9820-40e8-a7b7-e17ce2d7e971','analytics-admin@example.invalid','{}'),('ac3baced-065d-4629-80b6-412ec5ec57ec','analytics-client@example.invalid','{}');
INSERT INTO user_roles(user_id,role) VALUES('4c1895bb-9820-40e8-a7b7-e17ce2d7e971','admin');
INSERT INTO site_analytics_config(id,key_hash) VALUES(true,digest(repeat('a',64),'sha256'));
SELECT analytics_test_assert(NOT has_table_privilege('authenticated','site_analytics_events','SELECT,INSERT,UPDATE,DELETE,TRUNCATE'),'events are private from direct client access');
SELECT analytics_test_assert(NOT has_table_privilege('anon','site_analytics_config','SELECT'),'collector key digest is private');
SET LOCAL ROLE anon;
SELECT analytics_test_denied($q$SELECT record_site_visit(analytics_test_event('6d5459bd-8d7d-4199-8175-44d66a8b870a','/'),'invalid')$q$,'42501','unsigned telemetry denied');
SELECT analytics_test_denied($q$SELECT site_analytics_report()$q$,'42501','anonymous report access denied');
SELECT analytics_test_assert(site_analytics_collector_ready(repeat('a',64)),'collector handshake verifies the current key');
SELECT analytics_test_assert(NOT site_analytics_collector_ready(repeat('c',64)),'collector handshake rejects a mismatched hosting key');
SELECT analytics_test_denied($q$SELECT rotate_site_analytics_key()$q$,'42501','anonymous rotation denied');
SELECT record_site_visit(analytics_test_event('6d5459bd-8d7d-4199-8175-44d66a8b870a','/'),repeat('a',64));
SELECT record_site_visit(analytics_test_event('6d5459bd-8d7d-4199-8175-44d66a8b870a','/'),repeat('a',64));
SELECT record_site_visit(analytics_test_event('58f90cd7-d1a9-4e1a-81c9-86d7a7c11c74','/cart'),repeat('a',64));
SELECT record_site_visit(analytics_test_event('1b4911bc-624b-40d8-b51d-7f355c42a2cc','/marketplace','US')||'{"visitor_id":"1f72c7ce-30b6-4f1b-a64a-7ced0d09680c","session_id":"da71f9d3-9be6-41b8-80b8-05e6c6d64fb6"}',repeat('a',64));
SELECT record_site_visit(analytics_test_event('2a764708-1cb9-42c1-8829-f265d19ceab3','/about',NULL)||'{"visitor_id":"910d8b91-5481-4f77-800c-b148511fbdd5","session_id":"b8a72e69-d105-436b-9628-1445e8439624"}',repeat('a',64));
SELECT record_site_visit(analytics_test_event('cdf7f5fd-8871-4809-9afc-db65bd1fe152','/')||'{"event_name":"heartbeat"}',repeat('a',64));
SELECT record_site_visit(analytics_test_event('c0e21c6c-b762-486b-bb1a-281fbe011724','/')||'{"event_name":"heartbeat"}',repeat('a',64));
SELECT analytics_test_denied($q$SELECT record_site_visit(analytics_test_event('2f026ce4-8c21-41eb-8301-b1e959ffb1b8','/pets/private-id'),repeat('a',64))$q$,'22023','raw private route identifiers rejected');
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claim.sub','ac3baced-065d-4629-80b6-412ec5ec57ec',true);
SELECT analytics_test_denied($q$SELECT site_analytics_report()$q$,'42501','customer cannot read visitor data');
SELECT analytics_test_denied($q$SELECT rotate_site_analytics_key()$q$,'42501','customer cannot rotate key');
SELECT set_config('request.jwt.claim.sub','4c1895bb-9820-40e8-a7b7-e17ce2d7e971',true);
SELECT analytics_test_assert((site_analytics_report(1)->'metrics'->>'page_views')::int=4,'duplicate events and heartbeats do not inflate page views');
SELECT analytics_test_assert((site_analytics_report(1)->'metrics'->>'visitors')::int=3,'distinct browser counts are measured');
SELECT analytics_test_assert((site_analytics_report(1)->'metrics'->>'sessions')::int=3,'sessions count distinct measured visits');
SELECT analytics_test_assert((site_analytics_report(1)->'metrics'->>'engaged_sessions')::int=1,'engaged sessions use measured views or heartbeats');
SELECT analytics_test_assert((site_analytics_report(1)->'metrics'->>'visible_seconds')::int=60,'visible time uses declared thirty-second estimates');
SELECT analytics_test_assert((site_analytics_report(1)->'metrics'->>'located_views')::int=3,'unknown location stays unknown');
SELECT analytics_test_assert((site_analytics_report(1,'NG')->'metrics'->>'page_views')::int=2,'country filter scopes traffic');
SELECT analytics_test_assert(jsonb_array_length(site_analytics_report(7)->'daily')=7,'daily report includes zero-traffic days');
SELECT analytics_test_assert(EXISTS(SELECT 1 FROM jsonb_array_elements(site_analytics_report(1)->'countries') row WHERE row->>'label'='Unknown'),'location table exposes coverage gaps');
SELECT analytics_test_assert(jsonb_array_length(site_analytics_report(1)->'landing')=3,'one landing page per measured session');
SELECT analytics_test_denied($q$SELECT site_analytics_report(999)$q$,'22023','unbounded reporting windows rejected');
SELECT analytics_test_denied($q$SELECT site_analytics_report(1,'NGA')$q$,'22023','invalid country filter rejected');
RESET ROLE;
SELECT analytics_test_assert((site_analytics_report(1)->'registrations'->>'total')::int=(SELECT count(*) FROM profiles),'registration metrics come from actual records');
-- Trusted fixture inserts an expired row; the next collection purges it.
INSERT INTO site_analytics_events(id,occurred_at,visitor_id,session_id,event_name,path,device,browser,os) VALUES('56520483-4684-433a-b0fa-1f46066b332a',now()-interval '91 days','4b45cbf8-2040-4664-a220-f2ccb1a8b60c','3ad574e0-f75f-4919-b694-493d553e3544','page_view','/','desktop','Other','Other');
SELECT record_site_visit(analytics_test_event('6d5459bd-8d7d-4199-8175-44d66a8b870a','/'),repeat('a',64));
SELECT analytics_test_assert(NOT EXISTS(SELECT 1 FROM site_analytics_events WHERE id='56520483-4684-433a-b0fa-1f46066b332a'),'expired event cleanup runs during collection');
UPDATE site_analytics_limits SET hits=240 WHERE key=repeat('b',64);
INSERT INTO site_analytics_limits(key,minute,hits) VALUES(repeat('b',64),date_trunc('minute',clock_timestamp())+interval '1 minute',240) ON CONFLICT(key,minute) DO UPDATE SET hits=240;
SELECT analytics_test_assert(NOT record_site_visit(analytics_test_event('2f026ce4-8c21-41eb-8301-b1e959ffb1b8','/'),repeat('a',64)),'excessive request rate is limited');
SELECT analytics_test_assert(NOT EXISTS(SELECT 1 FROM site_analytics_events WHERE id='2f026ce4-8c21-41eb-8301-b1e959ffb1b8'),'rate-limited event is not stored');
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claim.sub','4c1895bb-9820-40e8-a7b7-e17ce2d7e971',true);
DO $$DECLARE token text;BEGIN token:=rotate_site_analytics_key();PERFORM analytics_test_assert(length(token)=64,'admin generates dedicated collector key');END$$;
SELECT analytics_test_denied($q$SELECT record_site_visit(analytics_test_event('2f026ce4-8c21-41eb-8301-b1e959ffb1b8','/'),repeat('a',64))$q$,'42501','rotation invalidates previous key');
RESET ROLE;
SELECT analytics_test_assert(EXISTS(SELECT 1 FROM audit_logs WHERE user_id='4c1895bb-9820-40e8-a7b7-e17ce2d7e971' AND action='site_analytics_key_rotated'),'collector rotation is audited');
